      "after_item": "S13_CAUTION",
      "title_raw": "빈 용기 처리 주의사항",
      "reason": "필드없음",
      "statements": [
        {
          "value": "빈용기라도 잔류물이 남아 있으므로, 경고표지를 떼지말 것. 폐기물 관리법에 명시된 경우 규정에 명시된 주의사항을 고려할 것.",
          "line": "p8:L14"
        }
      ],
      "line": "p8:L14"
    }
  ]
}

